'use client';
import React,{useState,useEffect,useRef} from 'react';
import {HeartHandshake,LayoutDashboard,Users,PackageCheck,Boxes,Wallet,ShieldCheck,ArrowUpRight,ArrowRight,Plus,Search,ChevronDown,ChevronRight,ArrowDownLeft,ArrowUpLeft,Check,CheckCheck,CalendarDays,LockKeyhole,LogOut,Settings2,X,MoreHorizontal,Pencil,Trash2,RotateCcw,Loader2,Info,FlaskConical,Mail,Menu,Heart,Leaf,Download,CheckCircle2,AlertCircle} from 'lucide-react';
import {roles,baskets,type Role} from './lib/domain';
type Page='dashboard'|'families'|'deliveries'|'stock'|'finance'|'team';
const money=(n:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n/100);
const day=(s:string)=>s?new Date(s.includes('T')?s:s+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'}):'Data a definir';
const when=(s:string)=>new Date(s).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'});
const initials=(s:string)=>s.split(/[ @]/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const nav=[{id:'dashboard',label:'Visão geral',icon:LayoutDashboard},{id:'families',label:'Famílias',icon:Users},{id:'deliveries',label:'Retiradas',icon:PackageCheck},{id:'stock',label:'Estoque de cestas',icon:Boxes},{id:'finance',label:'Financeiro',icon:Wallet},{id:'team',label:'Equipe e acessos',icon:ShieldCheck}];
const titles:Record<Page,string>={dashboard:'Visão geral',families:'Famílias',deliveries:'Retiradas',stock:'Estoque de cestas',finance:'Financeiro',team:'Equipe e acessos'};
function BasketArt(){return <svg className="basket-art" viewBox="0 0 330 230" fill="none" aria-hidden="true"><circle cx="183" cy="122" r="104" fill="white" opacity=".06"/><circle cx="183" cy="122" r="78" stroke="white" strokeDasharray="3 8" opacity=".15"/><path d="M121 111C89 50 127 25 139 48L165 113" fill="#EAC995"/><path d="m119 69 16-7m-8 25 16-7" stroke="#C49256" strokeWidth="4" strokeLinecap="round"/><path d="M184 113c-1-30 11-48 28-66 5 21 2 35-9 48 20-18 36-18 44-15-7 19-25 34-46 38" fill="#A5D7B5"/><path d="m197 118 16-53" stroke="#579E80" strokeWidth="3"/><rect x="149" y="61" width="36" height="74" rx="8" transform="rotate(-8 149 61)" fill="#F5F0E7"/><path d="m153 64 7-12 14-2 11 10" fill="#BCD4F9"/><rect x="156" y="86" width="25" height="18" rx="4" fill="#89B0F3"/><path d="M101 112h139l-15 77a11 11 0 0 1-11 9h-86a11 11 0 0 1-11-9l-16-77Z" fill="#C5D9FF"/><path d="m110 135 123 0m-119 20h115m-111 20h107M135 115l9 79m21-79 3 79m28-79-4 79m27-79-10 79" stroke="#83A9EF" strokeWidth="3"/><rect x="94" y="107" width="153" height="16" rx="8" fill="#E9F1FF"/><path d="M140 109c0-52 68-52 68 0" stroke="#E9F1FF" strokeWidth="8"/><circle cx="246" cy="168" r="28" fill="#F6C971"/><path d="m234 168 8 8 16-18" stroke="#714B0A" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"/><path d="M77 69v13m-6-6h12m180 33v13m-6-6h12" stroke="#B7D0FF" strokeWidth="2" strokeLinecap="round"/><circle cx="92" cy="167" r="4" fill="#B7D0FF"/><circle cx="244" cy="50" r="3" fill="#F6C971"/></svg>}
function Logo(){return <div className="brand"><span className="brand-icon"><HeartHandshake size={25}/></span><div>solidário<span className="brand-dot">.</span><small>CUIDAR, JUNTOS.</small></div></div>}
function Empty({title,detail,action}:{title:string;detail:string;action?:React.ReactNode}){return <div className="empty"><span><HeartHandshake size={29}/></span><h3>{title}</h3><p>{detail}</p>{action}</div>}
function Badge({done,children}:{done?:boolean;children:React.ReactNode}){return <span className={'badge '+(done?'green':'amber')}><i/>{children}</span>}
export default function ProjectApp({identity,signIn,signOut}:{identity:any;signIn:string;signOut:string}){
 const [data,setData]=useState<any>(null),[error,setError]=useState(''),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[page,setPage]=useState<Page>('dashboard'),[profile,setProfile]=useState(''),[modal,setModal]=useState<any>(null),[toast,setToast]=useState(''),[search,setSearch]=useState(''),[filter,setFilter]=useState('all'),[sidebar,setSidebar]=useState(false),[refreshTick,setRefreshTick]=useState(0);
 const closeRef=useRef<HTMLButtonElement>(null);
 useEffect(()=>{if(!identity){setLoading(false);return}setLoading(true);fetch('/api/project'+(profile?'?profile='+profile:''),{cache:'no-store'}).then(async r=>{const d:any=await r.json();if(!r.ok)throw Error(d.error);setData(d);setError('')}).catch(e=>setError(e.message)).finally(()=>setLoading(false))},[identity,profile,refreshTick]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(t)},[toast]);
 useEffect(()=>{if(!modal)return;const prev=document.activeElement as HTMLElement;closeRef.current?.focus();const key=(e:KeyboardEvent)=>{if(e.key==='Escape'&&!busy)setModal(null);if(e.key==='Tab'){const nodes=Array.from(document.querySelectorAll<HTMLElement>('[role="dialog"] button, [role="dialog"] input, [role="dialog"] select, [role="dialog"] textarea')).filter(x=>!x.hasAttribute('disabled'));const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};document.addEventListener('keydown',key);const old=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',key);document.body.style.overflow=old;prev?.focus()}},[modal?.type,busy]);
 async function act(action:string,payload:any={},success='Alteração salva.'){
  if(busy)return;setBusy(true);try{const r=await fetch('/api/project'+(profile?'?profile='+profile:''),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,payload})});const d:any=await r.json();if(!r.ok)throw Error(d.error);setData(d);setModal(null);setToast(success);return true}catch(e:any){setToast(e.message);return false}finally{setBusy(false)}
 }
 async function authAction(action:string,payload:any={},message='Alteração concluída.'){
  if(busy)return;setBusy(true);try{const r=await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...payload})});const d:any=await r.json();if(!r.ok)throw Error(d.error);if(d.path)setModal({type:'reset-link',email:d.email,url:new URL(d.path,window.location.origin).href});else{setModal(null);setRefreshTick(x=>x+1)}setToast(message)}catch(e:any){setToast(e.message)}finally{setBusy(false)}
 }
 async function nativeLogout(e:React.MouseEvent<HTMLAnchorElement>){if(identity.provider!=='password')return;e.preventDefault();try{await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'logout'})});window.location.href='/acesso'}catch{setToast('Não foi possível sair. Tente novamente.')}}
 const navigate=(p:Page)=>{setPage(p);setSearch('');setFilter('all');setSidebar(false)};
 const switchRole=(value:string)=>{setProfile(value);navigate('dashboard')};
 if(!identity)return <div className="login"><div className="login-story"><Logo/><div className="login-copy"><span className="eyebrow">PROJETO SOLIDÁRIO</span><h1>O cuidado começa<br/>quando a gente<br/><em>se une.</em></h1><p>Cada família tem uma história.<br/>Juntos, podemos fazer parte dela.</p><BasketArt/></div><div className="login-foot"><Heart size={16}/> Feito para quem faz o bem.</div></div><div className="login-form"><div className="private"><LockKeyhole size={13}/> Ambiente privado</div><div><span className="mini-icon"><HeartHandshake size={28}/></span><h2>Bem-vinda ao Solidário.</h2><p>Um só lugar para cuidar das famílias,<br/>organizar as cestas e acompanhar cada entrega.</p><a className="btn primary wide" href={signIn} target="_top">Entrar com minha conta <ArrowRight size={18}/></a><div className="login-note"><ShieldCheck size={19}/><span>Seu acesso é individual e seguro.<br/>Entre com o e-mail e a senha cadastrados.</span></div></div><small>Projeto Solidário · Igreja Batista Palavra Viva</small></div></div>;
 if(loading&&!data)return <div className="loading-screen"><Logo/><Loader2 className="spin"/><p>Preparando seu espaço de cuidado…</p></div>;
 if(error)return <div className="error-screen"><Logo/><AlertCircle size={38}/><h2>Não foi possível acessar o painel</h2><p>{error}</p><button className="btn primary" onClick={()=>setRefreshTick(x=>x+1)}>Tentar novamente</button><a href={identity.provider==='password'?'/acesso':signOut} onClick={nativeLogout} target="_top">Sair da conta</a></div>;
 if(!data)return null;
 const role:Role=data.user.role,admin=role==='admin',financial=role!=='common',actualAdmin=data.user.actualRole==='admin';
 const families=data.families as any[], deliveries=data.deliveries.filter((d:any)=>d.eventId===data.eventId),currentEvent=data.events.find((e:any)=>e.id===data.eventId),stock=data.totals.stock;
 const delivered=(id:string)=>deliveries.find((d:any)=>d.familyId===id);
 const pending=families.filter(f=>!delivered(f.id)),needed=pending.reduce((a,f)=>a+baskets(f.residents),0),people=families.reduce((a,f)=>a+f.residents,0),progress=families.length?Math.round(deliveries.length/families.length*100):0;
 const normalized=(s:string)=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const found=families.filter(f=>normalized(f.name+' '+f.phone+' '+f.neighborhood).includes(normalized(search))&&(filter==='all'||filter==='done'&&delivered(f.id)||filter==='pending'&&!delivered(f.id)));
 const correctionFamily=modal?.type==='delivery-edit'?families.find(f=>f.id===modal.familyId):null;
 const moneyValue=(f:FormData,key:string)=>Math.round(Number(String(f.get(key)||'0').replace(',','.'))*100);
 function download(){const header=['Responsável','Contato','Bairro','Endereço','Moradores','Retirada no evento'];const rows=found.map(f=>[f.name,f.phone,f.neighborhood,f.address,f.residents,delivered(f.id)?'Efetuada':'Pendente']);const csv='\uFEFF'+[header,...rows].map(row=>row.map(v=>'"'+String(v).replace(/^[=+@-]/,"'").replaceAll('"','""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='familias-projeto-solidario.csv';a.click();URL.revokeObjectURL(a.href);setToast('Lista exportada.')}
 function familyTable(list:any[],compact=false){return <div className="table-scroll"><table><thead><tr><th>Responsável</th>{!compact&&<th>Contato</th>}<th>Bairro</th><th>{compact?'Retirada':'Moradores'}</th>{!compact&&<th>Retirada</th>}<th><span className="sr-only">Ações</span></th></tr></thead><tbody>{list.map(f=><tr key={f.id}><td><div className="person"><span className="avatar small" style={{background:['#eaf0fe','#f1edfa','#e8f2ec','#fff2df'][f.name.length%4]}}>{initials(f.name)}</span><div><strong>{f.name}</strong><small>{f.demo?'Cadastro de exemplo':'Família cadastrada'}</small></div></div></td>{!compact&&<td>{f.phone}</td>}<td>{f.neighborhood}</td><td>{compact?<Badge done={!!delivered(f.id)}>{delivered(f.id)?'Retirada efetuada':'Pendente'}</Badge>:<span className="residents"><Users size={14}/>{f.residents}</span>}</td>{!compact&&<td><Badge done={!!delivered(f.id)}>{delivered(f.id)?'Efetuada':'Pendente'}</Badge></td>}<td className="actions">{!compact&&<button className="icon-btn" title={'Editar '+f.name} onClick={()=>setModal({type:'family',item:f})}><Pencil size={15}/></button>}<button className="icon-btn" title={'Ver família '+f.name} onClick={()=>setModal({type:'detail',item:f})}><ChevronRight size={18}/></button></td></tr>)}</tbody></table></div>}
 return <div className="shell">
  {sidebar&&<div className="sidebar-shade" onClick={()=>setSidebar(false)}/>}
  <aside className={'sidebar '+(sidebar?'mobile-open':'')}><Logo/><div className="workspace-name"><span>PS</span><div>Projeto Solidário<small>Gestão da ação social</small></div><ChevronDown size={14}/></div><div className="nav-label">ORGANIZAÇÃO</div><nav>{nav.filter(n=>n.id!=='finance'||financial).filter(n=>n.id!=='team'||admin).map(n=><button key={n.id} className={page===n.id?'active':''} onClick={()=>navigate(n.id as Page)}><n.icon size={19}/>{n.label}{n.id==='families'&&<span className="nav-count">{families.length}</span>}</button>)}</nav><div className="sidebar-bottom"><div className="verse"><Heart size={18}/><p>“O que fizerem a um destes meus pequeninos irmãos, a mim o fizeram.”</p><small>Mateus 25:40</small></div><div className="sidebar-private"><LockKeyhole size={14}/><span>Acesso privado<small>Somente pessoas autorizadas</small></span></div><a className="user-profile" href={identity.provider==='password'?'/acesso':signOut} onClick={nativeLogout} target="_top" title="Sair da conta"><span className="avatar">{initials(data.user.name)}</span><div><strong>{data.user.name.split('@')[0]}</strong><small>{roles[role]}</small></div><LogOut size={16}/></a></div></aside>
  <div className="main"><header className="topbar"><div className="breadcrumb"><button className="icon-btn mobile-menu" aria-label="Abrir menu" onClick={()=>setSidebar(true)}><Menu size={22}/></button><span>Projeto Solidário</span><ChevronRight size={14}/><strong>{titles[page]}</strong></div><div className="top-right"><span className="private"><LockKeyhole size={12}/> Acesso restrito</span><span className="header-date">{new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'short',year:'numeric'})}</span><span className="avatar small">{initials(data.user.name)}</span></div></header>
  {actualAdmin&&<div className={'prototype-bar '+(profile?'testing':'')}><span><FlaskConical size={15}/>{profile?`Testando perfil ${roles[role].toLowerCase()}. As ações alteram os dados do protótipo.`:'Protótipo interativo · explore o fluxo com dados de exemplo.'}</span><label>Testar como <select aria-label="Testar perfil" value={profile} onChange={e=>switchRole(e.target.value)}><option value="">Administrador</option><option value="common">Comum</option><option value="finance">Financeiro</option></select></label></div>}
  <main className="content" aria-busy={loading||busy}>
   <div className="page-heading"><div><div className="eyebrow">{page==='dashboard'?'CUIDADO QUE SE TRANSFORMA EM AÇÃO':'PROJETO SOLIDÁRIO'}</div><h1>{page==='dashboard'?`Olá, ${data.user.name.split(/[ @]/)[0]}. Vamos fazer o bem?`:titles[page]}</h1><p>{{dashboard:'Acompanhe o que estamos construindo juntos.',families:'Cada cadastro é uma família que podemos acolher.',deliveries:'Organize as entregas e registre cada gesto de cuidado.',stock:'Cada cesta conta. Acompanhe as entradas e saídas.',finance:'Transparência para transformar recursos em cuidado.',team:'Pessoas certas, com o acesso de que precisam.'}[page]}</p></div><div className="heading-actions">{page==='dashboard'?<button className="btn primary" onClick={()=>setModal({type:'family'})}><Plus size={17}/> Cadastrar família</button>:page==='families'?<><button className="btn secondary" onClick={download}><Download size={16}/> Exportar</button><button className="btn primary" onClick={()=>setModal({type:'family'})}><Plus size={17}/> Nova família</button></>:page==='finance'?<button className="btn primary" onClick={()=>setModal({type:'donation'})}><Plus size={17}/> Registrar arrecadação</button>:page==='stock'&&financial?<button className="btn primary" onClick={()=>setModal({type:'purchase'})}><Plus size={17}/> Confirmar entrada</button>:page==='team'?<><button className="btn secondary" onClick={()=>setModal({type:'backup'})}><Download size={17}/> Backup para migração</button><a className="btn primary" href="/acesso"><LockKeyhole size={17}/> Minha senha e acesso</a></>:null}</div></div>
   {families.length===0&&admin&&!data.demoLoaded&&<div className="welcome-banner"><span className="welcome-icon"><FlaskConical size={23}/></span><div><strong>Seu espaço está pronto para começar.</strong><p>Experimente famílias, arrecadações e retiradas fictícias para conhecer todo o fluxo.</p></div><button className="btn secondary" disabled={busy} onClick={()=>act('demo.load',{},'Dados de exemplo carregados. Vamos testar!')}>Carregar exemplos <ArrowRight size={16}/></button></div>}
   {page==='dashboard'&&<>
    <div className="stats"><Stat label="Famílias cadastradas" value={families.length} icon={Users} tone="blue" detail={`${people} pessoas acolhidas`} go={()=>navigate('families')}/><Stat label="Cestas em estoque" value={stock} icon={Boxes} tone="violet" detail="Prontas para fazer a diferença" go={()=>navigate('stock')}/><Stat label="Retiradas efetuadas" value={deliveries.length} icon={PackageCheck} tone="green" detail={`${families.length?progress:0}% das famílias deste evento`} go={()=>navigate('deliveries')}/><Stat label="Aguardando retirada" value={pending.length} icon={HeartHandshake} tone="orange" detail="Famílias para acolher neste evento" go={()=>navigate('deliveries')}/></div>
    <div className="dashboard-grid"><section className="hero"><div><span className="hero-label"><span/> CUIDAR É UM GESTO COLETIVO</span><h2>Pequenos gestos.<br/>Mesas mais cheias.</h2><p>Por trás de cada cesta, uma família.<br/>Por trás de cada entrega, todos nós.</p><button onClick={()=>navigate('deliveries')}>Organizar retiradas <ArrowUpRight size={17}/></button></div><BasketArt/><span className="hero-footer"><Heart size={13}/> Solidariedade que chega a quem precisa.</span></section><section className="panel event-panel"><div className="panel-title"><h2>Nosso próximo encontro</h2>{admin&&<button title="Configurar evento" className="icon-btn" onClick={()=>setModal({type:'event'})}><Settings2 size={17}/></button>}</div><div className="event-date"><CalendarDays size={21}/><div><strong>{day(currentEvent.date)}</strong><small>{currentEvent.name}</small></div></div><div className="progress-title"><span>Famílias atendidas</span><strong>{deliveries.length} <small>/ {families.length}</small></strong></div><div className="progress"><i style={{width:progress+'%'}}/></div><div className="event-summary"><CheckCircle2 size={16}/><span>{pending.length?`${pending.length} famílias ainda aguardam nossa entrega.`:families.length?'Todas as famílias foram atendidas!':'Cadastre a primeira família para começar.'}</span></div><button className="text-link" onClick={()=>navigate('deliveries')}>Ver lista de retiradas <ArrowRight size={16}/></button></section></div>
    <div className="dashboard-grid lower"><section className="panel"><div className="panel-title"><div><h2>Famílias em nosso cuidado</h2><p>Os cadastros mais recentes do projeto</p></div><button className="text-link" onClick={()=>navigate('families')}>Ver todas <ArrowUpRight size={15}/></button></div>{families.length?familyTable(families.slice(0,5),true):<Empty title="Toda história começa com uma família" detail="Cadastre os responsáveis para organizar o acolhimento." action={<button className="text-link" onClick={()=>setModal({type:'family'})}>Cadastrar família <ArrowRight size={16}/></button>}/>}</section><section className="panel activity"><div className="panel-title"><h2>Aconteceu por aqui</h2><span className="tiny-label">RECENTE</span></div>{data.activity.length?<div className="timeline">{data.activity.slice(0,4).map((a:any)=><div key={a.id}><span className="timeline-dot"><Check size={12}/></span><p><strong>{a.message}</strong><small>{a.by.split('@')[0]} · {when(a.at)}</small></p></div>)}</div>:<Empty title="Vamos escrever essa história?" detail="As atividades do projeto aparecerão aqui."/>}<div className="caring-note"><Leaf size={18}/><span>Organização também é uma forma de cuidar.</span></div></section></div>
   </>}
   {page==='families'&&<section className="panel"><div className="table-toolbar"><div className="search"><Search size={18}/><input placeholder="Buscar nome, contato ou bairro…" aria-label="Buscar famílias" value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="filter-tabs">{[['all','Todas'],['pending','Pendentes'],['done','Atendidas']].map(([v,l])=><button key={v} className={filter===v?'selected':''} onClick={()=>setFilter(v)}>{l}</button>)}</div></div>{found.length?familyTable(found):<Empty title="Nenhuma família encontrada" detail={search?'Tente outro nome, contato ou bairro.':'Comece cadastrando uma família ou ajuste o filtro.'}/>}<div className="table-footer">{found.length} de {families.length} famílias <span><ShieldCheck size={13}/> Dados acessíveis somente à equipe autorizada</span></div></section>}
   {page==='deliveries'&&<>
    <div className="event-bar"><CalendarDays size={19}/><div><strong>{currentEvent.name}</strong><span>{day(currentEvent.date)}</span></div>{admin&&<button className="text-link" onClick={()=>setModal({type:'event'})}>Gerenciar eventos <Settings2 size={15}/></button>}</div>
    <div className="stats three"><Stat label="Famílias atendidas" value={deliveries.length} icon={CheckCheck} tone="green" detail={`${progress}% de conclusão`}/><Stat label="Aguardando retirada" value={pending.length} icon={Users} tone="orange" detail={`${needed} cestas para atender a lista`}/><Stat label="Estoque disponível" value={stock} icon={Boxes} tone="blue" detail={stock>=needed?'Suficiente para a lista atual':`Faltam ${needed-stock} cestas para a lista`}/></div>
    <section className="panel"><div className="table-toolbar"><div className="search"><Search size={18}/><input placeholder="Buscar a família para registrar a retirada…" aria-label="Buscar retiradas" value={search} onChange={e=>setSearch(e.target.value)}/></div><select className="select-filter" aria-label="Filtrar retiradas" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Todas as famílias</option><option value="pending">Aguardando retirada</option><option value="done">Retiradas efetuadas</option></select></div><div className="table-scroll"><table><thead><tr><th>Família</th><th>Moradores</th><th>Cestas</th><th>Situação</th><th>Registro</th><th>Ação</th></tr></thead><tbody>{found.map(f=>{const d=delivered(f.id);return <tr key={f.id}><td><div className="person"><span className="avatar small">{initials(f.name)}</span><div><strong>{f.name}</strong><small>{f.neighborhood}</small></div></div></td><td>{f.residents}</td><td><strong>{d?d.quantity:baskets(f.residents)}</strong></td><td><Badge done={!!d}>{d?'Efetuada':'Pendente'}</Badge></td><td className="muted">{d?<>{when(d.at)}<small className="block">{d.by.split('@')[0]}</small>{!!d.corrections?.length&&<small className="block text-blue">Corrigida · {when(d.corrections.at(-1).at)}</small>}</>:'—'}</td><td>{!d?<button className="btn small-btn secondary" onClick={()=>setModal({type:'delivery',item:f})}><Check size={15}/> Registrar retirada</button>:admin?<div className="row-actions"><button className="btn small-btn secondary" aria-label={'Editar retirada de '+f.name} onClick={()=>setModal({type:'delivery-edit',item:d,familyId:''})}><Pencil size={14}/> Editar</button><button className="text-link muted" onClick={()=>setModal({type:'undo',item:d})}><RotateCcw size={14}/> Estornar</button></div>:<CheckCircle2 className="success-icon" size={19}/>}</td></tr>})}</tbody></table></div>{!found.length&&<Empty title="Nenhuma família nesta lista" detail="Cadastre uma família ou ajuste sua busca."/>}</section><div className="info-note"><Info size={16}/><span>Regra de entrega: 1–3 moradores recebem 1 cesta; 4–6 recebem 2. Cada família tem uma retirada por evento.</span></div>
   </>}
   {page==='stock'&&<>
    <div className="stats three"><Stat label="Cestas disponíveis" value={stock} icon={Boxes} tone="blue" detail="Estoque acumulado entre os eventos"/><Stat label="Entradas confirmadas" value={data.totals.incoming} icon={ArrowDownLeft} tone="green" detail="Compradas, montadas ou doadas"/><Stat label="Cestas entregues" value={data.totals.outgoing} icon={ArrowUpRight} tone="orange" detail="Total de saídas em todos os eventos"/></div>
    <div className="stock-callout"><span className="stock-icon"><Boxes size={27}/></span><div><h2>Da arrecadação à mesa de uma família.</h2><p>O estoque aumenta ao confirmar a compra, montagem ou recebimento de cestas. Cada retirada reduz o saldo automaticamente.</p></div>{financial&&<button className="btn secondary" onClick={()=>setModal({type:'basket'})}><Plus size={16}/> Recebi cestas doadas</button>}</div>
    <section className="panel"><div className="panel-title"><h2>Movimentações de estoque</h2><span className="tiny-label">TODOS OS EVENTOS</span></div><div className="table-scroll"><table><thead><tr><th>Movimentação</th><th>Descrição</th><th>Data e responsável</th><th>Quantidade</th>{financial&&<th>Ação</th>}</tr></thead><tbody>{[...(financial?data.entries.filter((e:any)=>e.quantity>0):[]).map((e:any)=>({...e,in:true})),...data.deliveries.map((d:any)=>({...d,note:families.find(f=>f.id===d.familyId)?.name||'Família',in:false}))].sort((a,b)=>b.at.localeCompare(a.at)).map((e:any)=><tr key={e.id}><td><span className={'movement '+(e.in?'in':'out')}>{e.in?<ArrowDownLeft size={16}/>:<ArrowUpRight size={16}/>} {e.in?'Entrada confirmada':'Entrega à família'}</span></td><td>{e.note}{!!e.corrections?.length&&<small className="block text-blue">Corrigido · {when(e.corrections.at(-1).at)}</small>}</td><td>{when(e.at)}<small className="block muted">{e.by.split('@')[0]}</small></td><td><strong className={e.in?'text-green':'text-blue'}>{e.in?'+':'−'}{e.quantity} cesta(s)</strong></td>{financial&&<td>{(e.in||admin)&&<button className="btn small-btn secondary" aria-label={'Editar movimentação '+e.note} onClick={()=>setModal({type:e.in?'entry-edit':'delivery-edit',item:e,familyId:''})}><Pencil size={14}/> Editar</button>}</td>}</tr>)}</tbody></table></div>{!financial&&<div className="info-note inset"><Info size={15}/> Entradas totais disponíveis acima. Detalhes das compras são restritos ao financeiro.</div>}{!data.deliveries.length&&!data.entries.length&&<Empty title="As cestas começam por aqui" detail="Confirme uma entrada para disponibilizar cestas para a entrega."/>}</section>
   </>}
   {page==='finance'&&financial&&<>
    <div className="stats"><Stat label="Total arrecadado" value={money(data.totals.raised)} icon={Heart} tone="blue" detail="Todas as contribuições registradas"/><Stat label="Investido em cestas" value={money(data.totals.spent)} icon={PackageCheck} tone="violet" detail="Compras e montagens confirmadas"/><Stat label="Saldo disponível" value={money(data.totals.balance)} icon={Wallet} tone="green" detail="Arrecadado menos compras"/><Stat label="Podemos montar" value={`${data.totals.possible} cestas`} icon={Boxes} tone="orange" detail={`Com o saldo e custo de ${money(data.cost)}`}/></div>
    <>{data.totals.balance<0&&<div className="deficit-note"><AlertCircle size={18}/><span>Após as correções, os gastos superam as arrecadações em <strong>{money(-data.totals.balance)}</strong>. A estimativa de novas cestas fica em zero até recompor o saldo.</span></div>}</><div className="finance-grid"><section className="panel financial-action"><div className="panel-title"><h2>Transformar recursos em cestas</h2><span className="icon-tile blue"><Boxes size={21}/></span></div><p>O valor arrecadado mostra o que é possível. Confirme a compra ou montagem para dar entrada no estoque.</p><button className="btn primary" onClick={()=>setModal({type:'purchase'})}>Confirmar compra ou montagem <ArrowRight size={16}/></button></section><section className="panel financial-action"><div className="panel-title"><h2>Custo de referência</h2><button className="icon-btn" title="Alterar custo por cesta" onClick={()=>setModal({type:'cost'})}><Pencil size={17}/></button></div><strong className="cost-value">{money(data.cost)} <small>/ cesta</small></strong><p>Usado na estimativa de montagem. O custo real da compra é registrado na confirmação.</p></section></div>
    <section className="panel"><div className="panel-title"><h2>Histórico financeiro</h2><span className="tiny-label">VALORES EM REAIS</span></div><div className="table-scroll"><table><thead><tr><th>Tipo</th><th>Descrição</th><th>Responsável e data</th><th>Valor</th><th>Ação</th></tr></thead><tbody>{data.entries.filter((e:any)=>e.type!=='basket').sort((a:any,b:any)=>b.at.localeCompare(a.at)).map((e:any)=><tr key={e.id}><td><span className={'movement '+(e.type==='donation'?'in':'out')}>{e.type==='donation'?<ArrowDownLeft size={17}/>:<ArrowUpRight size={17}/>} {e.type==='donation'?'Arrecadação':'Compra / montagem'}</span></td><td>{e.note}{e.quantity>0&&<small className="block muted">{e.quantity} cestas adicionadas ao estoque</small>}</td><td>{e.by.split('@')[0]}<small className="block muted">{when(e.at)}</small>{!!e.corrections?.length&&<small className="block text-blue">Corrigido · {when(e.corrections.at(-1).at)}</small>}</td><td className={e.type==='donation'?'text-green':''}><strong>{e.type==='donation'?'+':'−'} {money(e.amount)}</strong></td><td><button className="btn small-btn secondary" aria-label={'Editar lançamento '+e.note} onClick={()=>setModal({type:'entry-edit',item:e})}><Pencil size={14}/> Editar</button></td></tr>)}</tbody></table></div>{!data.entries.length&&<Empty title="Um gesto pode começar uma corrente" detail="Registre a primeira arrecadação para planejar as próximas cestas."/>}</section>
   </>}
   {page==='team'&&admin&&<>
    <div className="access-note"><ShieldCheck size={23}/><div><strong>Você está no controle dos acessos.</strong><p>Cada pessoa escolhe seu e-mail e sua senha na tela de cadastro. Confirme a identidade de quem solicitou acesso e aprove com o perfil adequado. Os cadastros pendentes não acessam dados. Somente contas aprovadas acessam os dados.</p></div></div>{!!data.registrations?.length&&<section className="panel pending-registrations"><div className="panel-title"><div><h2>Cadastros aguardando aprovação</h2><p>Confirme a identidade da pessoa antes de liberar o acesso. O e-mail não é verificado automaticamente.</p></div><span className="role-badge common">{data.registrations.length} pendente(s)</span></div><div className="table-scroll"><table><thead><tr><th>Pessoa</th><th>Solicitação</th><th>Ação</th></tr></thead><tbody>{data.registrations.map((r:any)=><tr key={r.id}><td><div className="person"><span className="avatar small">{initials(r.name)}</span><div><strong>{r.name}</strong><small>{r.email}</small></div></div></td><td>{when(r.createdAt)}</td><td><div className="row-actions"><button className="btn small-btn primary" onClick={()=>setModal({type:'approve',item:r})}><Check size={14}/> Aprovar</button><button className="text-link muted" onClick={()=>setModal({type:'reject-registration',item:r})}>Recusar</button></div></td></tr>)}</tbody></table></div></section>}<section className="panel"><div className="panel-title"><h2>Contas do projeto</h2><span className="muted">{data.members.length} conta(s)</span></div><div className="table-scroll"><table><thead><tr><th>Pessoa</th><th>Perfil</th><th>Acesso interno</th><th>Conta vinculada</th><th>Ação</th></tr></thead><tbody>{data.members.map((m:any)=><tr key={m.id}><td><div className="person"><span className="avatar small">{initials(m.name)}</span><div><strong>{m.name}</strong><small>{m.email}</small></div></div></td><td><span className={'role-badge '+m.role}>{roles[m.role as Role]}</span></td><td><Badge done={m.active}>{m.active?'Ativo':'Desativado'}</Badge></td><td className="muted">{m.userId?'Vinculada':'Aguardando primeiro acesso'}</td><td><div className="row-actions">{m.role==='admin'?<span className="muted"><LockKeyhole size={16}/></span>:<button className="btn small-btn secondary" onClick={()=>setModal({type:'member',item:m})}><Pencil size={14}/> Editar acesso</button>}{m.credentialId&&<button className="text-link" disabled={busy} onClick={()=>setModal({type:'request-reset',item:m})}>Redefinir senha</button>}</div></td></tr>)}</tbody></table></div></section>
    <div className="permission-grid">{(['common','finance','admin'] as Role[]).map(r=><section className="panel permission-card" key={r}><span className={'icon-tile '+(r==='common'?'blue':r==='finance'?'green':'violet')}>{r==='common'?<Users size={20}/>:r==='finance'?<Wallet size={20}/>:<ShieldCheck size={20}/>}</span><h3>{roles[r]}</h3><p>{r==='common'?'Cadastra e edita famílias, consulta o estoque e registra retiradas.':r==='finance'?'Todas as funções comuns, além de arrecadações, custo por cesta e confirmação de entradas.':'Todas as funções, gestão de permissões, eventos, correção e estorno de retiradas.'}</p></section>)}</div>
   </>}
   <footer className="page-footer"><span>Projeto Solidário <i/> Cuidar, juntos.</span><span><ShieldCheck size={13}/> Acesso privado · dados salvos automaticamente</span></footer>
  </main></div>
  {toast&&<div className="toast" role="status"><Info size={18}/><span>{toast}</span><button aria-label="Fechar aviso" onClick={()=>setToast('')}><X size={16}/></button></div>}
  {modal&&<div className="modal-shade" onMouseDown={e=>{if(e.target===e.currentTarget&&!busy)setModal(null)}}><section role="dialog" aria-modal="true" aria-labelledby="modal-title" className={'modal '+(modal.type==='family'?'large':'')}><div className="modal-header"><div><span className="eyebrow">PROJETO SOLIDÁRIO</span><h2 id="modal-title">{{family:modal.item?'Editar família':'Acolher uma nova família',detail:'Informações da família',delivery:'Confirmar retirada',undo:'Estornar retirada',donation:'Registrar arrecadação',purchase:'Confirmar compra ou montagem',basket:'Recebimento de cestas doadas',cost:'Custo de referência',member:modal.item?'Editar acesso':'Cadastrar conta',event:'Organizar evento',delete:'Excluir cadastro',clear:'Limpar dados de exemplo','entry-edit':'Editar lançamento','delivery-edit':'Corrigir família da retirada',approve:'Aprovar cadastro','reject-registration':'Recusar cadastro','request-reset':'Gerar link de redefinição','reset-link':'Link para redefinir a senha',backup:'Backup completo do projeto'}[modal.type as string]}</h2></div><button ref={closeRef} className="icon-btn" disabled={busy} aria-label="Fechar janela" onClick={()=>setModal(null)}><X size={21}/></button></div>
   {modal.type==='family'&&<form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);act('family.save',{...Object.fromEntries(f),id:modal.item?.id},'Família salva com sucesso.')}}><p className="modal-intro">Preencha os dados do responsável e de sua família.</p><div className="form-grid"><label className="full">Nome do responsável<input name="name" minLength={3} maxLength={100} required defaultValue={modal.item?.name} placeholder="Nome completo" autoComplete="name"/></label><label>Contato com DDD<input name="phone" required minLength={10} maxLength={30} defaultValue={modal.item?.phone} placeholder="(11) 99999-9999" autoComplete="tel"/></label><label>Quantidade de moradores<input name="residents" type="number" min="1" max="6" step="1" required defaultValue={modal.item?.residents||''} placeholder="Incluindo o responsável"/><small>Regra definida para famílias de até 6 moradores.</small></label><label className="full">Endereço<input name="address" minLength={5} maxLength={200} required defaultValue={modal.item?.address} placeholder="Rua, número e complemento" autoComplete="street-address"/></label><label className="full">Bairro<input name="neighborhood" minLength={2} maxLength={80} required defaultValue={modal.item?.neighborhood} placeholder="Bairro da família"/></label><label className="full">Observações <span className="optional">opcional</span><textarea name="notes" maxLength={500} defaultValue={modal.item?.notes} placeholder="Informações que ajudam no acolhimento" rows={3}/></label></div><div className="form-foot"><span><LockKeyhole size={13}/> Dados protegidos</span><button type="button" className="btn secondary" disabled={busy} onClick={()=>setModal(null)}>Cancelar</button><Submit busy={busy}>{modal.item?'Salvar alterações':'Cadastrar família'}</Submit></div></form>}
   {modal.type==='detail'&&<><div className="detail-person"><span className="avatar">{initials(modal.item.name)}</span><div><h3>{modal.item.name}</h3><Badge done={!!delivered(modal.item.id)}>{delivered(modal.item.id)?'Retirada efetuada':'Aguardando retirada'}</Badge></div></div><dl className="detail-list"><div><dt>Contato</dt><dd>{modal.item.phone}</dd></div><div><dt>Moradores</dt><dd>{modal.item.residents} pessoas</dd></div><div><dt>Endereço</dt><dd>{modal.item.address}</dd></div><div><dt>Bairro</dt><dd>{modal.item.neighborhood}</dd></div>{modal.item.notes&&<div><dt>Observações</dt><dd>{modal.item.notes}</dd></div>}</dl><div className="form-foot"><button className="icon-btn danger" title="Excluir cadastro" onClick={()=>setModal({type:'delete',item:modal.item})}><Trash2 size={18}/></button><button className="btn secondary" onClick={()=>setModal({type:'family',item:modal.item})}><Pencil size={15}/> Editar</button>{!delivered(modal.item.id)&&<button className="btn primary" onClick={()=>setModal({type:'delivery',item:modal.item})}><Check size={16}/> Registrar retirada</button>}</div></>}
   {(modal.type==='delivery'||modal.type==='undo'||modal.type==='delete'||modal.type==='clear')&&<><div className="confirm-icon"><PackageCheck size={29}/></div><p className="confirm-text">{modal.type==='delivery'?<>Confirmar a entrega de <strong>{baskets(modal.item.residents)} cesta(s)</strong> para <strong>{modal.item.name}</strong>?</>:modal.type==='undo'?<>Estornar esta retirada e devolver <strong>{modal.item.quantity} cesta(s)</strong> ao estoque?</>:modal.type==='delete'?<>Excluir o cadastro de <strong>{modal.item.name}</strong>? Esta ação não pode ser desfeita.</>:<>Remover os dados fictícios? Suas contas e permissões serão mantidas.</>}</p>{modal.type==='delivery'&&<div className={'confirmation-info '+(stock<baskets(modal.item.residents)?'insufficient':'')}><Boxes size={19}/><span>{stock<baskets(modal.item.residents)?'Estoque insuficiente para esta retirada.':`Estoque: ${stock} → ${stock-baskets(modal.item.residents)} cestas após a entrega.`}</span></div>}<div className="form-foot"><button className="btn secondary" disabled={busy} onClick={()=>setModal(null)}>Cancelar</button><button className="btn primary" disabled={busy||(modal.type==='delivery'&&stock<baskets(modal.item.residents))} onClick={()=>act(modal.type==='delivery'?'delivery.create':modal.type==='undo'?'delivery.undo':modal.type==='delete'?'family.delete':'demo.clear',{id:modal.item?.id},modal.type==='delivery'?'Retirada registrada. Obrigado por cuidar!':'Alteração concluída.')}>{busy?<Loader2 className="spin" size={17}/>:<Check size={17}/>} Confirmar</button></div></>}
   {['donation','purchase','basket','cost'].includes(modal.type)&&<form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);act(modal.type==='cost'?'cost.save':modal.type+'.create',modal.type==='cost'?{cost:moneyValue(f,'cost')}:{amount:moneyValue(f,'amount'),quantity:Number(f.get('quantity')),note:f.get('note')},modal.type==='donation'?'Arrecadação registrada.':modal.type==='cost'?'Custo de referência atualizado.':'Entrada confirmada no estoque.')}}><p className="modal-intro">{modal.type==='donation'?'Registre o valor recebido. O estoque será atualizado apenas ao confirmar uma compra ou montagem.':modal.type==='purchase'?'Confirme apenas cestas já compradas ou montadas. A entrada e o gasto serão registrados juntos.':modal.type==='basket'?'Registre apenas as cestas prontas que já foram recebidas em doação.':'A estimativa será recalculada. Os gastos de compras anteriores serão preservados.'}</p>{modal.type==='purchase'&&<div className="balance-note">Saldo disponível <strong>{money(data.totals.balance)}</strong></div>}<div className="form-grid">{modal.type==='cost'?<label className="full">Custo por cesta (R$)<input name="cost" type="number" step="0.01" min="0.01" max="1000000" defaultValue={(data.cost/100).toFixed(2)} required/></label>:<>{modal.type!=='donation'&&<label className="full">Quantidade de cestas<input name="quantity" type="number" min="1" max="10000" required placeholder="0" onChange={e=>{if(modal.type==='purchase'){const amount=e.currentTarget.form?.elements.namedItem('amount') as HTMLInputElement;if(amount)amount.value=(Number(e.target.value)*data.cost/100).toFixed(2)}}}/></label>}{modal.type!=='basket'&&<label className="full">{modal.type==='purchase'?'Valor total da compra (R$)':'Valor arrecadado (R$)'}<input name="amount" type="number" step="0.01" min="0.01" max="1000000" required placeholder="0,00"/></label>}<label className="full">Descrição<input name="note" minLength={3} maxLength={200} required placeholder={modal.type==='donation'?'Ex.: contribuição da comunidade':'Ex.: compra de cestas no mercado'}/></label></>}</div><div className="form-foot"><button type="button" className="btn secondary" disabled={busy} onClick={()=>setModal(null)}>Cancelar</button><Submit busy={busy}>{modal.type==='cost'?'Salvar custo':modal.type==='donation'?'Registrar valor':'Confirmar entrada'}</Submit></div></form>}
   {modal.type==='entry-edit'&&<form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);act('entry.edit',{id:modal.item.id,expected:{amount:modal.item.amount,quantity:modal.item.quantity,note:modal.item.note},amount:moneyValue(f,'amount'),quantity:Number(f.get('quantity')),note:f.get('note'),reason:f.get('reason')},'Lançamento corrigido. Saldo e estoque recalculados.')}}><p className="modal-intro">Corrija os dados deste lançamento. Os totais serão recalculados, e a data e o responsável pelo registro original serão preservados.</p><div className="original-record"><span>Registrado em {when(modal.item.at)}</span><strong>{modal.item.type==='donation'?'Arrecadação':modal.item.type==='purchase'?'Compra / montagem':'Cestas doadas'}</strong><p>{modal.item.note}</p></div><div className="form-grid">{modal.item.type!=='donation'&&<label className="full">Quantidade de cestas<input name="quantity" type="number" min="1" max="10000" step="1" required defaultValue={modal.item.quantity}/></label>}{modal.item.type!=='basket'&&<label className="full">{modal.item.type==='donation'?'Valor arrecadado (R$)':'Valor total da compra (R$)'}<input name="amount" type="number" step="0.01" min="0.01" max="1000000" required defaultValue={(modal.item.amount/100).toFixed(2)}/></label>}<label className="full">Descrição<input name="note" minLength={3} maxLength={200} required defaultValue={modal.item.note}/></label><label className="full">Motivo da correção<textarea name="reason" minLength={3} maxLength={300} required rows={2} placeholder="Ex.: valor digitado incorretamente"/></label></div><CorrectionHistory items={modal.item.corrections}/><div className="form-foot"><button type="button" className="btn secondary" disabled={busy} onClick={()=>setModal(null)}>Cancelar</button><Submit busy={busy}>Salvar correção</Submit></div></form>}
   {modal.type==='delivery-edit'&&<form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);act('delivery.edit',{id:modal.item.id,expected:{familyId:modal.item.familyId,quantity:modal.item.quantity},familyId:modal.familyId,reason:f.get('reason')},'Retirada corrigida. Família e estoque atualizados.')}}><p className="modal-intro">Escolha quem realmente recebeu as cestas. A família registrada por engano voltará a ficar pendente neste evento.</p><div className="original-record"><span>{data.events.find((e:any)=>e.id===modal.item.eventId)?.name} · {when(modal.item.at)}</span><strong>{families.find(f=>f.id===modal.item.familyId)?.name}</strong><p>{modal.item.quantity} cesta(s) registradas</p></div><div className="form-grid"><label className="full">Família correta<select aria-label="Família correta" required value={modal.familyId} onChange={e=>setModal({...modal,familyId:e.target.value})}><option value="" disabled>Selecione a família que recebeu</option>{families.filter(f=>f.id!==modal.item.familyId).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR')).map(f=>{const done=data.deliveries.some((d:any)=>d.eventId===modal.item.eventId&&d.familyId===f.id&&d.id!==modal.item.id);return <option key={f.id} value={f.id} disabled={done}>{f.name}{done?' · já recebeu neste evento':''}</option>})}</select></label>{correctionFamily&&<div className="correction-preview full"><div><span>Moradores</span><strong>{correctionFamily.residents}</strong></div><div><span>Cestas da retirada</span><strong>{modal.item.quantity} → {baskets(correctionFamily.residents)}</strong></div><div><span>Estoque após corrigir</span><strong>{stock+modal.item.quantity-baskets(correctionFamily.residents)}</strong></div></div>}<label className="full">Motivo da correção<textarea name="reason" minLength={3} maxLength={300} rows={2} required placeholder="Ex.: selecionei a família errada"/></label></div><CorrectionHistory items={modal.item.corrections}/><div className="form-foot"><button type="button" className="btn secondary" disabled={busy} onClick={()=>setModal(null)}>Cancelar</button><button type="submit" className="btn primary" disabled={busy||!correctionFamily||stock+modal.item.quantity-baskets(correctionFamily.residents)<0}>{busy&&<Loader2 className="spin" size={16}/>}Salvar correção</button></div>{correctionFamily&&stock+modal.item.quantity<baskets(correctionFamily.residents)&&<p className="correction-error">Estoque insuficiente para a família selecionada.</p>}</form>}
   {modal.type==='approve'&&<form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);act('registration.approve',{id:modal.item.id,role:f.get('role')},'Cadastro aprovado. A pessoa já pode acessar com sua senha.')}}><p className="modal-intro">Você está liberando o acesso de <strong>{modal.item.name}</strong> ({modal.item.email}). Escolha o perfil de trabalho.</p><div className="form-grid"><label className="full">Perfil de acesso<select name="role" defaultValue="common"><option value="common">Comum — famílias, estoque e retiradas</option><option value="finance">Financeiro — também arrecadações, compras e custos</option></select></label></div><div className="form-foot"><button type="button" className="btn secondary" disabled={busy} onClick={()=>setModal(null)}>Cancelar</button><Submit busy={busy}>Aprovar cadastro</Submit></div></form>}
   {modal.type==='reject-registration'&&<><p className="modal-intro">Recusar o cadastro de <strong>{modal.item.name}</strong> ({modal.item.email})? Esta conta não poderá entrar no sistema.</p><div className="form-foot"><button className="btn secondary" disabled={busy} onClick={()=>setModal(null)}>Cancelar</button><button className="btn primary" disabled={busy} onClick={()=>authAction('reject-registration',{id:modal.item.id},'Cadastro recusado.')}>Recusar cadastro</button></div></>}
   {modal.type==='request-reset'&&<><p className="modal-intro">Gerar um link para <strong>{modal.item.email}</strong> escolher uma nova senha? O link vale por 15 minutos, só pode ser usado uma vez e substitui links anteriores. Você pode encaminhá-lo diretamente à pessoa.</p><div className="form-foot"><button className="btn secondary" disabled={busy} onClick={()=>setModal(null)}>Cancelar</button><button className="btn primary" disabled={busy} onClick={()=>authAction('reset-link',{id:modal.item.credentialId},'Link gerado. Encaminhe somente à pessoa indicada.')}>Gerar link</button></div></>}
   {modal.type==='reset-link'&&<><p className="modal-intro">Encaminhe este link somente para <strong>{modal.email}</strong>. A pessoa escolhe a senha ao abrir o link.</p><div className="form-grid"><label className="full">Link de redefinição<input type="text" readOnly value={modal.url} onFocus={e=>e.target.select()}/></label></div><div className="form-foot"><button className="btn secondary" onClick={()=>setModal(null)}>Fechar</button><button className="btn primary" onClick={()=>navigator.clipboard?.writeText(modal.url).then(()=>setToast('Link copiado.')).catch(()=>setToast('Selecione o link e copie manualmente.'))}>Copiar link</button></div></>}
   {modal.type==='backup'&&<><p className="modal-intro">O backup inclui os cadastros de famílias, o histórico financeiro, retiradas, permissões e contas com suas senhas protegidas por hash. Ele permite transferir o sistema sem pedir novas senhas à equipe.</p><div className="auth-info"><ShieldCheck size={19}/><span>Este arquivo contém dados pessoais e de acesso. Guarde em local privado e não envie para repositórios públicos.</span></div><div className="form-foot"><button className="btn secondary" onClick={()=>setModal(null)}>Fechar</button><a className="btn primary" href="/api/backup" download><Download size={16}/> Baixar backup completo</a></div></>}
   {modal.type==='member'&&<form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);act('member.save',{...Object.fromEntries(f),id:modal.item?.id,active:f.get('active')==='on'},'Permissões salvas.')}}><p className="modal-intro">Altere as permissões desta pessoa. As senhas são escolhidas pelos próprios usuários e não ficam visíveis à administração.</p><div className="form-grid"><label className="full">Nome<input name="name" minLength={2} maxLength={100} defaultValue={modal.item?.name} required placeholder="Nome da pessoa"/></label><label className="full">E-mail<input name="email" type="email" defaultValue={modal.item?.email} readOnly={!!modal.item} maxLength={180} required placeholder="nome@exemplo.com"/></label><label className="full">Perfil<select name="role" defaultValue={modal.item?.role||'common'}><option value="common">Comum</option><option value="finance">Financeiro</option></select></label><label className="checkbox full"><input name="active" type="checkbox" defaultChecked={modal.item?modal.item.active:true}/> Permitir acesso interno ao sistema</label></div><div className="form-foot"><button className="btn secondary" type="button" disabled={busy} onClick={()=>setModal(null)}>Cancelar</button><Submit busy={busy}>Salvar permissões</Submit></div></form>}
   {modal.type==='event'&&<><div className="event-selector"><label>Evento ativo<select value={data.eventId} disabled={busy} onChange={e=>act('event.select',{id:e.target.value},'Evento alterado. O estoque foi preservado.')}>{data.events.map((e:any)=><option key={e.id} value={e.id}>{e.name}</option>)}</select></label></div><form key={data.eventId} onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);act('event.save',{...Object.fromEntries(f),newEvent:f.get('newEvent')==='on'},'Evento salvo.')}}><p className="modal-intro">Um novo evento terá uma nova lista de retiradas. O estoque e o histórico financeiro continuam acumulados.</p><div className="form-grid"><label className="full">Nome do evento<input name="name" minLength={3} maxLength={100} required defaultValue={currentEvent.name}/></label><label className="full">Data da entrega<input name="date" type="date" required defaultValue={currentEvent.date}/></label><label className="checkbox full"><input type="checkbox" name="newEvent"/> Criar como novo evento</label></div><div className="form-foot"><button type="button" className="btn secondary" disabled={busy} onClick={()=>setModal(null)}>Cancelar</button><Submit busy={busy}>Salvar evento</Submit></div></form>{data.demoLoaded&&<button className="clear-demo text-link" onClick={()=>setModal({type:'clear'})}><RotateCcw size={14}/> Limpar dados de exemplo</button>}</>}
  </section></div>}
 </div>;
}
function Submit({busy,children}:{busy:boolean;children:React.ReactNode}){return <button className="btn primary" type="submit" disabled={busy}>{busy&&<Loader2 size={16} className="spin"/>}{children}</button>}
function Stat({label,value,icon:Icon,tone,detail,go}:{label:string;value:any;icon:any;tone:string;detail:string;go?:()=>void}){return <section className={'stat '+(go?'clickable':'')} onClick={go}><div className="stat-top"><span>{label}</span><span className={'icon-tile '+tone}><Icon size={19}/></span></div><strong>{value}</strong><p>{detail}</p>{go&&<button className="stat-open" aria-label={'Ver '+label} onClick={e=>{e.stopPropagation();go()}}><ArrowUpRight size={16}/></button>}</section>}

function CorrectionHistory({items}:{items?:any[]}){if(!items?.length)return null;return <details className="correction-history"><summary>Histórico de correções ({items.length})</summary>{[...items].reverse().map((c,i)=><div key={i}><strong>{when(c.at)} · {c.by}</strong><p>{c.description}</p><small>Motivo: {c.reason}</small></div>)}</details>}
